function queueSettings(settings) {
  const supported = [
    "instagram",
    "youtube",
    "tiktok",
    "facebook",
    "threads",
    "twitter",
    "linkedin",
    "bluesky",
    "pinterest",
  ];
  const { spreadsheetId, sheetName, targets, tiktokAiGenerated } = settings;
  if (
    !/^[A-Za-z0-9_-]{10,}$/.test(spreadsheetId) ||
    spreadsheetId.startsWith("YOUR_") ||
    typeof sheetName !== "string" ||
    !sheetName.trim()
  )
    throw Error("Configure the publishing worksheet.");
  if (
    !targets ||
    typeof targets !== "object" ||
    Object.keys(targets).some((key) => !supported.includes(key))
  ) {
    throw Error("Configure Blotato destinations by platform.");
  }
  const destinations = supported.flatMap((platform) => {
    const entry = targets[platform];
    if (!entry?.accountId) return [];
    if (
      typeof entry.accountId !== "string" ||
      !entry.accountId.trim() ||
      (platform === "facebook" && (typeof entry.pageId !== "string" || !entry.pageId.trim())) ||
      (platform === "pinterest" && (typeof entry.boardId !== "string" || !entry.boardId.trim()))
    ) {
      throw Error("Check the account and destination IDs for " + platform + ".");
    }
    return [
      {
        platform,
        accountId: entry.accountId.trim(),
        ...(platform === "facebook" ? { pageId: entry.pageId.trim() } : {}),
        ...(platform === "pinterest" ? { boardId: entry.boardId.trim() } : {}),
      },
    ];
  });
  if (!destinations.length || typeof tiktokAiGenerated !== "boolean")
    throw Error("Select at least one destination and set the TikTok AI label.");
  return {
    spreadsheetId,
    sheet: "'" + sheetName.replace(/'/g, "''") + "'",
    destinations,
    tiktokAiGenerated,
  };
}
export default ({ settings }) => ({ config: queueSettings(settings) });

