function sheetCell(sheet, column, row) {
  let letters = "";
  for (let index = column + 1; index > 0; index = Math.floor((index - 1) / 26)) {
    letters = String.fromCharCode(65 + ((index - 1) % 26)) + letters;
  }
  return sheet + "!" + letters + row;
}

function sheetRequest(config, row, status, receipts) {
  const make = (column, content) => ({
    range: sheetCell(config.sheet, column, row.rowNumber),
    values: [[content]],
  });
  const data = [make(row.statusColumn, status)];
  if (receipts) data.push(make(row.receiptsColumn, JSON.stringify(receipts)));
  return {
    spreadsheetId: config.spreadsheetId,
    valueInputOption: "RAW",
    includeValuesInResponse: true,
    responseValueRenderOption: "UNFORMATTED_VALUE",
    data,
  };
}

function unquoteSheet(range) {
  return range.replace(/^'(.*)'!/, (_match, tab) => tab.replace(/''/g, "'") + "!");
}

function checkSheet(response, request) {
  if (
    response?.spreadsheetId !== request.spreadsheetId ||
    response.totalUpdatedCells !== request.data.length ||
    response?.responses?.length !== request.data.length ||
    request.data.some((cell, i) => {
      const result = response.responses[i];
      const exact = unquoteSheet(cell.range);
      return (
        result.updatedCells !== 1 ||
        typeof result.updatedRange !== "string" ||
        ![exact, exact + ":" + exact.slice(exact.lastIndexOf("!") + 1)].includes(
          unquoteSheet(result.updatedRange),
        ) ||
        result.updatedData?.values?.[0]?.[0] !== cell.values[0][0]
      );
    })
  )
    throw Error("Google Sheets did not confirm the publishing status on the expected row.");
}
function publicMedia(value) {
  if (typeof value !== "string") return "";
  const url = value.trim();
  return /^https:\/\/(?:[a-z\d](?:[a-z\d-]*[a-z\d])?\.)+[a-z]{2,63}(?:[/?#][^\s\\]*)?$/i.test(url)
    ? url
    : "";
}

function makePosts(config, row, uploadedUrl) {
  return config.destinations.map((destination) => {
    const { platform, accountId, ...targetIds } = destination;
    const target = { targetType: platform, ...targetIds };
    if (platform === "youtube")
      Object.assign(target, {
        title: row.title,
        privacyStatus: "unlisted",
        shouldNotifySubscribers: false,
      });
    if (platform === "tiktok")
      Object.assign(target, {
        privacyLevel: "PUBLIC_TO_EVERYONE",
        disabledComments: false,
        disabledStitch: false,
        disabledDuet: false,
        isBrandedContent: false,
        isYourBrand: false,
        isAiGenerated: config.tiktokAiGenerated,
      });
    const mediaUrl =
      platform === "bluesky" || platform === "pinterest" ? row.imageUrl : uploadedUrl;
    return {
      post: { accountId, target, content: { platform, text: row.text, mediaUrls: [mediaUrl] } },
    };
  });
}

function submissionReceipt(response, post) {
  const id = response?.body?.postSubmissionId;
  return response?.statusCode === 201 && typeof id === "string" && id.trim()
    ? { platform: post.content.platform, postSubmissionId: id }
    : { platform: post.content.platform, outcome: "check_blotato" };
}

function finalStatus(receipts) {
  const ids = receipts.map((receipt) => receipt.postSubmissionId);
  return ids.length && ids.every(Boolean) && new Set(ids).size === ids.length
    ? "SUBMITTED"
    : "CHECK BLOTATO";
}
async function postBlotato(context, path, apiKey, body) {
  if (!apiKey) throw Error("Bind the Blotato API key.");
  try {
    const response = await context.fetch("https://backend.blotato.com/v2/" + path, {
      method: "POST",
      redirect: "manual",
      headers: { "content-type": "application/json", "blotato-api-key": apiKey },
      body: JSON.stringify(body),
    });
    return {
      statusCode: response.status,
      body: response.status === 201 ? await response.json() : null,
    };
  } catch {
    return null;
  }
}

export default async ({ work, row, config, apiKey }, context) => {
  if (!apiKey) throw Error("Bind the Blotato API key.");
  const write = async (status, receipts) => {
    const body = sheetRequest(config, row, status, receipts);
    checkSheet(await context.actions.call("googlesheets.update_values_batch", body), body);
  };
  const close = async (status, receipts) => {
    await write(status, receipts);
    return {
      next: {
        rowIndex: work.rowIndex + 1,
        posts: [],
        receipts: [],
        results: [...work.results, { rowNumber: row.rowNumber, status, receipts }],
      },
    };
  };
  if (work.posts.length === 0) {
    await write("SUBMITTING");
    const upload = await postBlotato(context, "media", apiKey, { url: row.mediaUrl });
    const uploaded = upload?.statusCode === 201 && publicMedia(upload.body?.url);
    if (!uploaded) return close("CHECK BLOTATO", [{ outcome: "upload_unconfirmed" }]);
    return { next: { ...work, posts: makePosts(config, row, uploaded) } };
  }
  const request = work.posts[work.receipts.length];
  const response = await postBlotato(context, "posts", apiKey, request);
  const receipts = [...work.receipts, submissionReceipt(response, request.post)];
  if (receipts.length === work.posts.length) return close(finalStatus(receipts), receipts);
  return { next: { ...work, receipts } };
};

